<?php
require __DIR__.'/_auth.php';$pdo=admin_db();if(!$pdo)exit('Database unavailable.');$id=(int)($_GET['id']??0);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'&&$id){$pdo->prepare('DELETE FROM pages WHERE id=?')->execute([$id]);header('Location:/admin/pages.php');exit;}$title=trim($_POST['title']??'');$slug=preg_replace('/[^a-z0-9-]+/','-',strtolower(trim($_POST['slug']??$title)));$body=trim($_POST['body']??'');$status=($_POST['status']??'draft')==='published'?'published':'draft';$data=[$slug,$title,$body,$status,trim($_POST['featured_image']??''),trim($_POST['meta_title']??''),trim($_POST['meta_description']??'')];if($id){$st=$pdo->prepare('UPDATE pages SET slug=?,title=?,body=?,status=?,featured_image=?,meta_title=?,meta_description=?,updated_at=NOW() WHERE id=?');$st->execute([...$data,$id]);}else{$st=$pdo->prepare('INSERT INTO pages(slug,title,body,status,featured_image,meta_title,meta_description,updated_at) VALUES(?,?,?,?,?,?,?,NOW())');$st->execute($data);$id=(int)$pdo->lastInsertId();}$msg='Page saved.';}
$page=null;if($id){$st=$pdo->prepare('SELECT * FROM pages WHERE id=?');$st->execute([$id]);$page=$st->fetch();}$list=$pdo->query('SELECT id,title,slug,status,updated_at FROM pages ORDER BY updated_at DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>Pages CMS</title></head><body><main class="section wrap"><div class="section-head"><div><span class="eyebrow dark-text">CMS</span><h1>Pages & SEO</h1></div><div><a class="btn light" href="/admin/">Dashboard</a> <a class="btn dark" href="/admin/pages.php">New Page</a></div></div><?php if($msg):?><p><strong><?=e($msg)?></strong></p><?php endif;?><div class="content-layout"><section><form class="contact-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="title" value="<?=e($page['title']??'')?>" placeholder="Page title" required><input name="slug" value="<?=e($page['slug']??'')?>" placeholder="slug"><textarea name="body" style="min-height:320px" placeholder="Page content. Basic HTML is allowed for trusted administrators."><?=e($page['body']??'')?></textarea><input name="featured_image" value="<?=e($page['featured_image']??'')?>" placeholder="Featured image path"><input name="meta_title" value="<?=e($page['meta_title']??'')?>" placeholder="SEO title"><textarea name="meta_description" placeholder="SEO description"><?=e($page['meta_description']??'')?></textarea><select name="status"><option value="draft" <?=($page['status']??'draft')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($page['status']??'')==='published'?'selected':''?>>Published</option></select><button class="btn gold">Save Page</button><?php if($id):?><button class="btn" name="action" value="delete" onclick="return confirm('Delete this page?')">Delete</button><?php endif;?></form></section><aside><h2>Existing Pages</h2><?php foreach($list as $r):?><p><a href="/admin/pages.php?id=<?=$r['id']?>"><strong><?=e($r['title'])?></strong></a><br><small>/<?=e($r['slug'])?> · <?=e($r['status'])?></small></p><?php endforeach;?></aside></div></main></body></html>
